{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-vxN2Ke/src/simulate.js","content":"/**
 * Parses a limiter file and simulates it, producing either the replay log
 * or the summary totals. Throws a LineError on any malformed input.
 */

import { BucketPolicy, WindowPolicy } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

export class LineError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function fail(line, reason) {
  throw new LineError(line, reason)
}

function checkName(line, field, value) {
  if (!NAME_RE.test(value)) fail(line, `invalid ${field} ${value}`)
}

function checkUint(line, field, value, min) {
  if (!UINT_RE.test(value) || BigInt(value) < min) {
    fail(line, `${field} must be an integer of at least ${min}`)
  }
  return BigInt(value)
}

export function simulate(mode, text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map() // name -> policy instance
  const routes = [] // { prefix, policyNames: [] }
  let eventsStarted = false
  let lastTick = null

  const outputLines = []
  const perKey = new Map() // key -> { allowed, denied }
  let totalAllowed = 0n
  let totalDenied = 0n

  for (let idx = 0; idx < rawLines.length; idx++) {
    const lineNo = idx + 1
    const trimmed = rawLines[idx].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (eventsStarted) fail(lineNo, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityStr, refillStr, perStr] = tokens
      checkName(lineNo, 'policy name', name)
      const capacity = checkUint(lineNo, 'capacity', capacityStr, 1n)
      const refill = checkUint(lineNo, 'refill', refillStr, 0n)
      const per = checkUint(lineNo, 'per', perStr, 1n)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new BucketPolicy(capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) fail(lineNo, 'expected window <name> <limit> <span>')
      const [, name, limitStr, spanStr] = tokens
      checkName(lineNo, 'policy name', name)
      const limit = checkUint(lineNo, 'limit', limitStr, 0n)
      const span = checkUint(lineNo, 'span', spanStr, 1n)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new WindowPolicy(limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) fail(lineNo, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      checkName(lineNo, 'route prefix', prefix)
      const policyNames = tokens.slice(2)
      for (const pname of policyNames) {
        if (!policies.has(pname)) fail(lineNo, `unknown policy ${pname}`)
      }
      if (routes.some((r) => r.prefix === prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      if (tokens.length !== 3) fail(lineNo, 'expected event <tick> <key>')
      const [, tickStr, key] = tokens
      const tick = checkUint(lineNo, 'tick', tickStr, 0n)
      checkName(lineNo, 'key', key)
      if (lastTick !== null && tick < lastTick) fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      eventsStarted = true

      let bestRoute = null
      for (const r of routes) {
        if (key.startsWith(r.prefix)) {
          if (bestRoute === null || r.prefix.length > bestRoute.prefix.length) bestRoute = r
        }
      }

      let allowed = true
      let denyPolicy = null

      if (bestRoute !== null) {
        for (const pname of bestRoute.policyNames) {
          policies.get(pname).advance(tick, key)
        }
        for (const pname of bestRoute.policyNames) {
          if (!policies.get(pname).allow(key)) {
            allowed = false
            denyPolicy = pname
            break
          }
        }
        if (allowed) {
          for (const pname of bestRoute.policyNames) {
            policies.get(pname).record(key, tick)
          }
        }
      }

      let stat = perKey.get(key)
      if (stat === undefined) {
        stat = { allowed: 0n, denied: 0n }
        perKey.set(key, stat)
      }
      if (allowed) {
        stat.allowed += 1n
        totalAllowed += 1n
      } else {
        stat.denied += 1n
        totalDenied += 1n
      }

      if (mode === 'replay') {
        outputLines.push(`${tick} ${key} ${allowed ? 'allow' : 'deny ' + denyPolicy}`)
      }
    } else {
      fail(lineNo, `unknown directive ${directive}`)
    }
  }

  if (mode === 'summary') {
    const keys = Array.from(perKey.keys()).sort()
    for (const key of keys) {
      const stat = perKey.get(key)
      outputLines.push(`${key} allowed=${stat.allowed} denied=${stat.denied}`)
    }
    outputLines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  }

  return outputLines.length === 0 ? '' : outputLines.join('\n') + '\n'
}
"}

